<script lang="ts">
 import {onMount} from 'svelte';import {prefersReducedMotion} from 'svelte/motion';
 let {text,reduced=false}:{text:string;reduced?:boolean}=$props();const uid=$props.id(),id='curve-'+uid.replace(/[^a-zA-Z0-9_-]/g,'');
 let root:HTMLSpanElement,measure:SVGTextElement,pathText:SVGTextPathElement,width=$state(154),spacing=$state(160),hot=$state(false),visible=true,raf=0,last=0,offset=0,velocity=0,alive=true;
 let quiet=$derived(reduced||prefersReducedMotion.current);let repetitions=$derived((text+'　▪　').repeat(Math.ceil((width+spacing)/spacing)+1));
 function tick(now:number){raf=0;if(!alive||quiet||!visible||document.hidden)return;const dt=last?Math.min(.05,(now-last)/1000):0;last=now;velocity+=((hot?-13:0)-velocity)*(1-Math.exp(-dt*12));offset=((offset+velocity*dt)%spacing+spacing)%spacing;pathText?.setAttribute('startOffset',String(offset-spacing));if(hot||Math.abs(velocity)>.1)raf=requestAnimationFrame(tick);}
 function wake(){if(!raf&&!quiet&&visible&&!document.hidden){last=0;raf=requestAnimationFrame(tick);}}
 function size(){width=Math.max(80,root.clientWidth);spacing=Math.max(40,measure?.getComputedTextLength()||160);}
 $effect(()=>{if(quiet){cancelAnimationFrame(raf);raf=0;}else wake();});
 onMount(()=>{const parent=root.closest('.island-place,.island-greeting')||root.parentElement!,enter=()=>{hot=true;wake();},leave=()=>queueMicrotask(()=>{if(alive){hot=false;wake();}});size();void document.fonts.ready.then(()=>{if(alive)size();});const resize=new ResizeObserver(size);resize.observe(root);const intersection=new IntersectionObserver(([entry])=>{visible=entry.isIntersecting;if(visible)wake();else{cancelAnimationFrame(raf);raf=0;}});intersection.observe(root);const visibility=()=>{if(document.hidden){cancelAnimationFrame(raf);raf=0;}else wake();};parent.addEventListener('pointerenter',enter);parent.addEventListener('pointerleave',leave);parent.addEventListener('focusin',enter);parent.addEventListener('focusout',leave);document.addEventListener('visibilitychange',visibility);return()=>{alive=false;cancelAnimationFrame(raf);resize.disconnect();intersection.disconnect();parent.removeEventListener('pointerenter',enter);parent.removeEventListener('pointerleave',leave);parent.removeEventListener('focusin',enter);parent.removeEventListener('focusout',leave);document.removeEventListener('visibilitychange',visibility);};});
</script>
<span bind:this={root} class="curved-loop" data-quiet={quiet} data-active={hot&&!quiet}><span class="loop-label">{text}</span><svg viewBox={`0 0 ${width} 28`} aria-hidden="true" focusable="false"><defs><path {id} d={`M0,20 Q${width/2},8 ${width+24},20`} fill="none"/></defs><text bind:this={measure} visibility="hidden">{text}　▪　</text><text><textPath bind:this={pathText} href={'#'+id} startOffset={-spacing}>{repetitions}</textPath></text></svg></span>
<style>.curved-loop{position:relative;display:block;width:100%;height:25px;font-size:12px;line-height:25px;color:inherit;overflow:hidden}.curved-loop svg{position:absolute;inset:0;width:100%;height:28px;display:block;fill:currentColor;font:12px 'Noto Sans SC','Microsoft YaHei',sans-serif;letter-spacing:.35px;user-select:none;pointer-events:none;opacity:0;transition:opacity .15s ease-out}.loop-label{display:block;white-space:nowrap;transition:opacity .15s ease-out}.curved-loop[data-active=true] svg{opacity:1}.curved-loop[data-active=true] .loop-label{opacity:0}.curved-loop[data-quiet=true] svg{display:none}.curved-loop[data-quiet=true] .loop-label{transition:none}</style>
